/**
 * Feature `archive` (Phase 4 slice 6b, GMP): retention of batch records, contingency packs, the PDF/A-3 true copy, the
 * certified evidence export and the read-only inspection workspace (contract ns/archive.ts; kernel 1170 to 1172; DI-40,
 * DI-41, DI-43, DI-46, DI-47, IN-08, IN-11, PR-16, PR-59). The rules are the database's: retention is computed by the
 * kernel engine from the inputs read here from the batch's record (facts.ts); forms, exports and reads go through the
 * records definers; certifying an export and signing a forms reconciliation are the signable action ARCHIVE_ACT.
 */
import {
  routes,
  type ArchiveBatchSummary,
  type ContingencyFormView,
  type ExportView,
  type FormsView,
  type RetentionView,
  type SignableAction,
} from '@ebmr/api-contract';
import { commands, records, toDbContext, type ActorContext } from '@ebmr/kernel';
import type { FastifyInstance } from 'fastify';
import type pg from 'pg';
import type { AppContext } from '../../platform/context.ts';
import { withActorCommand, withIdempotentActorCommand } from '../../platform/db/commands.ts';
import { bindRoutes } from '../../platform/http/bind.ts';
import { HttpRefusal, refusal } from '../../platform/http/refusal.ts';
import type { SignableActionHandler, SignableActionRegistry } from '../../platform/ports.ts';
import { peopleOf, personRef, usOf } from '../common/people.ts';
import { dbActHandler } from '../esig/db-acts.ts';
import { batchFacts, type BatchFacts } from './facts.ts';

type Db = Pick<pg.Pool, 'query'> | pg.PoolClient;
type ArchiveAct = Extract<SignableAction, { kind: 'ARCHIVE_ACT' }>;

const noBatch = (batchId: string) =>
  refusal(404, { code: 'EBMR-API-NO-BATCH', kind: 'INVALID_INPUT', whatHappened: 'This batch was not found.', why: `${batchId} is no batch.`, whatYouCanDo: ['Reload the batch list.'] });

/** ARCHIVE_ACT: QA certifies an evidence export (EVIDENCE_EXPORT_CERTIFIED) or signs a forms reconciliation (FORMS_RECONCILED). */
export function archiveActHandler(app: AppContext): SignableActionHandler<ArchiveAct> {
  return dbActHandler<ArchiveAct>(app, {
    kind: 'ARCHIVE_ACT',
    aggregateTypes: ['evidence_export', 'form_reconciliation'],
    target: (a) =>
      a.act === 'CERTIFY_EXPORT'
        ? { aggregateType: 'evidence_export', aggregateId: a.subjectId, meaning: 'EVIDENCE_EXPORT_CERTIFIED', expectedState: 'ASSEMBLED' }
        : { aggregateType: 'form_reconciliation', aggregateId: a.subjectId, meaning: 'FORMS_RECONCILED', expectedState: 'RECONCILED' },
    async apply(client, _ctx, a, signatureId) {
      if (a.act === 'CERTIFY_EXPORT') await records.certifyEvidenceExport(client, a.subjectId, signatureId);
      else await records.signFormReconciliation(client, a.subjectId, signatureId);
      return { act: a.act, subjectId: a.subjectId };
    },
  });
}

// ---------------------------------------------------------------------------------------------------------------------
// Reads
// ---------------------------------------------------------------------------------------------------------------------

async function facts(db: Db, batchId: string): Promise<BatchFacts> {
  const f = await batchFacts(db, batchId);
  if (!f) throw noBatch(batchId);
  return f;
}

function euOf(f: BatchFacts): Pick<RetentionView['inputs'], 'eu' | 'euDate'> {
  const eu = f.retention.eu;
  if (!eu) return { eu: 'NOT_IN_SET', euDate: null };
  return eu.state === 'PENDING' ? { eu: 'PENDING', euDate: null } : { eu: eu.state, euDate: eu.date };
}

interface OwnJson {
  status: 'DATED' | 'OPEN' | 'NONE';
  retainUntil: string | null;
  governingRules: string[];
  openReasons: string[];
}
interface EffectiveJson {
  status: 'DATED' | 'OPEN';
  retainUntil: string | null;
  governedBy: string[];
  openBecause: { recordKey: string; reasons: string[] }[];
}

export async function retentionView(app: AppContext, db: Db, f: BatchFacts): Promise<RetentionView> {
  const inputs = records.batchRetentionInputs(f.retention);
  const key = `batch:${f.batchId}`;
  const scheduled = (await db.query<{ s: boolean }>('select exists (select 1 from records.retention_schedule where record_key = $1) as s', [key])).rows[0]?.s ?? false;
  let status: 'DATED' | 'OPEN';
  let retainUntil: string | null;
  let governingRules: string[];
  let governedBy: string[];
  let openBecause: string[];
  const drift: string[] = [];
  if (scheduled) {
    const r = (await db.query<{ r: { own: OwnJson; effective: EffectiveJson; inputs: Record<string, unknown> } }>('select records.retention_of($1, $2) as r', ['batch', f.batchId])).rows[0]?.r;
    if (!r) throw new Error('retention was not read');
    status = r.effective.status;
    retainUntil = r.effective.retainUntil;
    governingRules = r.own.governingRules;
    governedBy = r.effective.governedBy;
    openBecause = r.effective.openBecause.flatMap((o) => o.reasons.map((x) => `${o.recordKey}: ${x}`));
    const now = (await db.query<{ n: Record<string, unknown> }>('select records.normalize_retention_inputs($1::jsonb) as n', [JSON.stringify(inputs)])).rows[0]?.n ?? {};
    for (const k of Object.keys(now).sort()) {
      if (JSON.stringify(now[k]) !== JSON.stringify(r.inputs[k])) drift.push(`${k}: stored ${JSON.stringify(r.inputs[k] ?? null)}, the record now gives ${JSON.stringify(now[k])}`);
    }
  } else {
    // The engine evaluates the rules of the record's retention key (a batch record's), as it does for a stored schedule.
    const own = (await db.query<{ o: OwnJson }>('select records.evaluate_retention($1::jsonb) as o', [JSON.stringify({ ...inputs, retentionKey: 'BATCH_RECORD' })])).rows[0]?.o;
    if (!own) throw new Error('retention was not evaluated');
    status = own.status === 'DATED' ? 'DATED' : 'OPEN';
    retainUntil = own.status === 'DATED' ? own.retainUntil : null;
    governingRules = own.governingRules;
    governedBy = own.status === 'DATED' ? [key] : [];
    openBecause = own.status === 'NONE' ? ['no retention rule applies yet'] : own.openReasons;
  }
  const reqs = (
    await db.query<{ outcome: 'REFUSED' | 'ELIGIBLE'; reason: string; person_id: string; at_us: string }>(
      `select outcome, reason, person_id, ${usOf('recorded_at')} as at_us from records.disposal_request where record_key = $1 order by recorded_at desc, id desc limit 20`,
      [key],
    )
  ).rows;
  const people = await peopleOf(db, reqs.map((x) => x.person_id));
  return {
    batchId: f.batchId,
    inputs: {
      markets: [...inputs.markets],
      licenceForm: f.retention.licenceForm,
      manufactureDate: f.retention.manufactureDate,
      expiryDate: f.retention.expiryDate,
      outcome: f.retention.outcome,
      abortCancelDate: f.retention.abortCancelDate,
      ...euOf(f),
    },
    status,
    retainUntil,
    governingRules,
    governedBy,
    openBecause,
    scheduled,
    drift,
    disposalRequests: reqs.map((x) => ({ outcome: x.outcome, reason: x.reason, by: personRef(people, x.person_id, 'QA_REVIEWER'), at: app.formatInstant(x.at_us) })),
  };
}

export async function formsView(app: AppContext, db: Db, batchId: string): Promise<FormsView> {
  const forms = (
    await db.query<{ id: string; serial: string; moment: 'ISSUE' | 'STAGE_START'; stage_ref: string | null; template_ref: string; destination: string; page_no: number; page_count: number; state: ContingencyFormView['state']; person_id: string; at_us: string }>(
      `select f.id, f.serial, f.moment, f.stage_ref, f.template_ref, f.destination, f.page_no, f.page_count, records.contingency_form_state(f.id) as state, f.person_id,
              ${usOf('f.recorded_at')} as at_us
         from records.contingency_form f where f.batch_id = $1 order by f.serial`,
      [batchId],
    )
  ).rows;
  const events = (
    await db.query<{ form_id: string; event: string; reason: string | null; reference: string | null; person_id: string; at_us: string }>(
      `select e.form_id, e.event, e.reason, e.reference, e.person_id, ${usOf('e.recorded_at')} as at_us from records.contingency_form_event e where e.batch_id = $1 order by e.recorded_at, e.id`,
      [batchId],
    )
  ).rows;
  const head = (
    await db.query<{ state: FormsView['state']; problem: string | null; signer: string | null; signed_us: string | null }>(
      `select records.form_reconciliation_state($1) as state, records.form_reconciliation_problem($1) as problem,
              (select r.person_id from records.form_reconciliation r where r.batch_id = $1) as signer,
              (select ${usOf('r.recorded_at')} from records.form_reconciliation r where r.batch_id = $1) as signed_us`,
      [batchId],
    )
  ).rows[0];
  const people = await peopleOf(db, [...forms.map((f) => f.person_id), ...events.map((e) => e.person_id), head?.signer]);
  return {
    batchId,
    state: head?.state ?? 'NONE',
    completionProblem: head?.problem ?? null,
    forms: forms.map((f) => ({
      formId: f.id,
      serial: f.serial,
      moment: f.moment,
      stageRef: f.stage_ref,
      templateRef: f.template_ref,
      destination: f.destination,
      page: `${f.page_no} of ${f.page_count}`,
      state: f.state,
      issuedBy: personRef(people, f.person_id, 'SHIFT_SUPERVISOR'),
      issuedAt: app.formatInstant(f.at_us),
      events: events.filter((e) => e.form_id === f.id).map((e) => ({ event: e.event, reason: e.reason, reference: e.reference, by: personRef(people, e.person_id, 'OPERATOR'), at: app.formatInstant(e.at_us) })),
    })),
    signedBy: head?.signer ? personRef(people, head.signer, 'QA_SHOP_FLOOR') : null,
    signedAt: head?.signed_us ? app.formatInstant(head.signed_us) : null,
  };
}

interface ExportRow {
  id: string;
  subject_id: string;
  subject_label: string;
  export_sha256: string;
  pdf_content_sha256: string;
  content_bytes: string;
  sections: records.EvidenceSection[];
  assembled_by_person: string;
  assembled_us: string;
  certified_by: string | null;
  certified_us: string | null;
  reads: number;
}

async function exportsWhere(app: AppContext, db: Db, where: string, params: unknown[]): Promise<ExportView[]> {
  const { rows } = await db.query<ExportRow>(
    `select e.id, e.subject_id, e.subject_label, e.export_sha256, e.pdf_content_sha256, e.content_bytes::text as content_bytes, e.sections,
            e.assembled_by_person, ${usOf('e.recorded_at')} as assembled_us, c.person_id as certified_by,
            case when c.export_id is null then null else ${usOf('c.recorded_at')} end as certified_us,
            (select count(*)::int from records.evidence_export_read x where x.export_id = e.id) as reads
       from records.evidence_export e left join records.evidence_export_certification c on c.export_id = e.id
      where e.subject_type = 'batch' and ${where} order by e.recorded_at desc, e.id`,
    params,
  );
  const people = await peopleOf(db, rows.flatMap((r) => [r.assembled_by_person, r.certified_by]));
  return rows.map((r) => ({
    exportId: r.id,
    batchId: r.subject_id,
    label: r.subject_label,
    state: r.certified_by ? 'CERTIFIED' : 'ASSEMBLED',
    exportSha256: r.export_sha256,
    pdfContentSha256: r.pdf_content_sha256,
    contentBytes: Number(r.content_bytes),
    sections: r.sections.map((s) => ({ name: s.name, kind: s.kind, title: s.title, chainKey: s.chainKey, sha256: s.sha256, bytes: s.bytes })),
    assembledBy: personRef(people, r.assembled_by_person, 'QA_REVIEWER'),
    assembledAt: app.formatInstant(r.assembled_us),
    certifiedBy: r.certified_by ? personRef(people, r.certified_by, 'QA_REVIEWER') : null,
    certifiedAt: r.certified_us ? app.formatInstant(r.certified_us) : null,
    reads: r.reads,
  }));
}

async function batchList(db: Db): Promise<ArchiveBatchSummary[]> {
  const { rows } = await db.query<{ id: string; batch_number: string; status: string | null; forms: ArchiveBatchSummary['formsState']; exports: number; certified: number }>(
    `select b.id, b.batch_number, s.state ->> 'status' as status, records.form_reconciliation_state(b.id) as forms,
            (select count(*)::int from records.evidence_export e where e.subject_type = 'batch' and e.subject_id = b.id::text) as exports,
            (select count(*)::int from records.evidence_export e join records.evidence_export_certification c on c.export_id = e.id
              where e.subject_type = 'batch' and e.subject_id = b.id::text) as certified
       from recipe.batch_execution b left join recipe.execution_state s on s.batch_id = b.id
      order by b.issued_at desc, b.id limit 200`,
  );
  return rows.map((r) => ({ batchId: r.id, batchNumber: r.batch_number, status: r.status ?? 'ISSUED', formsState: r.forms, exports: r.exports, certifiedExports: r.certified }));
}

// ---------------------------------------------------------------------------------------------------------------------
// Copies
// ---------------------------------------------------------------------------------------------------------------------

/** One read-only REPEATABLE READ command of the actor: every query sees one snapshot (as the QP package assembly). */
async function inSnapshot<T>(pool: pg.Pool, who: ActorContext, work: (c: pg.PoolClient) => Promise<T>): Promise<T> {
  const client = await pool.connect();
  try {
    await client.query('begin isolation level repeatable read');
    await client.query('select kernel.begin_command($1::jsonb)', [JSON.stringify(toDbContext(who))]);
    const result = await work(client);
    await client.query('commit');
    return result;
  } catch (error) {
    await client.query('rollback');
    if (error instanceof HttpRefusal) throw error;
    throw commands.asKernelError(error);
  } finally {
    client.release();
  }
}

const noRecord = (f: BatchFacts) =>
  refusal(409, { code: 'EBMR-API-ARCHIVE', kind: 'NOT_ALLOWED', whatHappened: 'There is no record of this batch to copy yet. Nothing was recorded.', why: `Batch ${f.batchNumber} has no audit trail.`, controls: ['DI-41'], whatYouCanDo: ['Copy the batch once it has been issued.'] });

async function batchBundle(c: pg.PoolClient, f: BatchFacts): Promise<records.TrueCopyBundle> {
  const bundle = await records.trueCopyBundleFromSnapshot(c, `batch:${f.batchId}`);
  if ((JSON.parse(bundle.manifest) as records.Manifest).head === null) throw noRecord(f);
  return bundle;
}

const pdfTitle = (f: BatchFacts) => `Batch record ${f.batchNumber} (true copy)`;

interface BuiltExport {
  bundles: { name: string; title: string; bundle: records.TrueCopyBundle }[];
  exp: records.EvidenceExport;
}

async function buildExport(c: pg.PoolClient, app: AppContext, f: BatchFacts): Promise<BuiltExport> {
  const bundles: BuiltExport['bundles'] = [{ name: 'batch-record', title: `Batch record ${f.batchNumber}`, bundle: await batchBundle(c, f) }];
  for (const [prefix, name, title] of [
    ['batch_review', 'batch-review', `Review and audit-trail review of ${f.batchNumber}`],
    ['form_reconciliation', 'contingency-forms', `Contingency forms of ${f.batchNumber}`],
  ] as const) {
    const b = await records.trueCopyBundleFromSnapshot(c, `${prefix}:${f.batchId}`);
    if ((JSON.parse(b.manifest) as records.Manifest).head !== null) bundles.push({ name, title, bundle: b });
  }
  const pdf = await records.renderTrueCopyPdf((bundles[0] as BuiltExport['bundles'][number]).bundle, { title: pdfTitle(f), label: `Batch ${f.batchNumber}` });
  const generatedAt = (await c.query<{ t: string }>(`select to_char(clock_timestamp() at time zone 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.US"Z"') as t`)).rows[0]?.t ?? '';
  const summary = {
    batchId: f.batchId,
    batchNumber: f.batchNumber,
    status: f.status,
    retention: await retentionView(app, c, f),
    forms: await formsView(app, c, f.batchId),
  };
  const exp = records.assembleEvidenceExport({
    subject: { type: 'batch', id: f.batchId, label: `Batch ${f.batchNumber}` },
    generatedAt,
    bundles,
    pdfs: [{ name: 'batch-record-pdf', title: `Batch record ${f.batchNumber} (PDF/A-3)`, chainKey: `batch:${f.batchId}`, pdf: pdf.pdf, contentSha256: pdf.contentSha256 }],
    documents: [{ name: 'summary', title: 'Batch summary: status, retention and paper forms', mediaType: 'application/json', text: JSON.stringify(summary, null, 2) }],
  });
  return { bundles, exp };
}

async function one<T>(list: Promise<T[]>, what: string): Promise<T> {
  const x = (await list)[0];
  if (!x) throw new Error(`${what} was not found after it was recorded`);
  return x;
}

export function registerSignableActions(registry: SignableActionRegistry, app: AppContext): void {
  if (app.installation !== 'GMP') return;
  registry.register(archiveActHandler(app));
}

export function plugin(scope: FastifyInstance, app: AppContext): Promise<void> {
  const pool = app.pools.app;
  bindRoutes(scope, app, routes.archive, {
    batches: async ({ requireSession }) => {
      requireSession();
      return { batches: await batchList(pool) };
    },
    batch: async ({ params, requireSession }) => {
      requireSession();
      const f = await facts(pool, params.batchId);
      return {
        batchId: f.batchId,
        batchNumber: f.batchNumber,
        status: f.status,
        retention: await retentionView(app, pool, f),
        forms: await formsView(app, pool, f.batchId),
        exports: await exportsWhere(app, pool, 'e.subject_id = $1', [f.batchId]),
      };
    },
    syncRetention: async ({ params, body, actor, idempotencyKey, requestHash }) => {
      const f = await facts(pool, params.batchId);
      await withIdempotentActorCommand(pool, actor(), idempotencyKey ?? '', requestHash, async (c) => {
        const inputs = records.batchRetentionInputs(f.retention);
        const key = `batch:${f.batchId}`;
        const exists = (await c.query<{ s: boolean }>('select exists (select 1 from records.retention_schedule where record_key = $1) as s', [key])).rows[0]?.s;
        if (exists) {
          await records.updateRetentionInputs(c, key, inputs, body.reason);
        } else {
          const type = (await c.query<{ code: string }>("select code from records.record_register where retention_key = 'BATCH_RECORD' order by code limit 1")).rows[0]?.code;
          if (!type) {
            throw refusal(409, {
              code: 'EBMR-API-ARCHIVE', kind: 'NOT_ALLOWED', whatHappened: 'The retention of this batch was not stored. Nothing was recorded.',
              why: 'The record register has no approved record type with the batch-record retention key (DI-01).', controls: ['DI-47', 'DI-01'],
              whatYouCanDo: ['Ask QA to approve the batch record type in the record register first.'],
            });
          }
          await records.createRetentionSchedule(c, 'batch', f.batchId, type, inputs);
        }
        // A processing record follows the packaging records packed from it (dependency inheritance, DI-47).
        for (const [sup, dep] of [...f.supports.map((d) => [f.batchId, d]), ...f.dependsOn.map((s) => [s, f.batchId])] as [string, string][]) {
          const both = (await c.query<{ n: number }>('select count(*)::int as n from records.retention_schedule where record_key in ($1, $2)', [`batch:${sup}`, `batch:${dep}`])).rows[0]?.n;
          if (both === 2) await records.linkRetentionDependency(c, `batch:${sup}`, `batch:${dep}`, 'BULK_PACKED_INTO');
        }
        return null;
      });
      return retentionView(app, pool, f);
    },
    requestDisposal: async ({ params, body, actor, idempotencyKey, requestHash }) => {
      await facts(pool, params.batchId);
      const out = await withIdempotentActorCommand(pool, actor(), idempotencyKey ?? '', requestHash, async (c) => {
        const a = await records.requestDisposal(c, 'batch', params.batchId, body.reason);
        return { outcome: a.outcome, retainUntil: a.retainUntil, refusals: a.refusals };
      });
      return out.result;
    },
    issuePack: async ({ params, body, actor, idempotencyKey, requestHash }) => {
      const f = await facts(pool, params.batchId);
      if (['EXECUTION_COMPLETE', 'ABORTED', 'CANCELLED'].includes(f.status)) {
        throw refusal(409, {
          code: 'EBMR-API-ARCHIVE', kind: 'NOT_ALLOWED', whatHappened: 'No contingency pack was issued.', why: `Batch ${f.batchNumber} is ${f.status}: packs are issued at its issue or at a stage start.`,
          controls: ['DI-43'], whatYouCanDo: ['Issue packs for a batch that is issued or in progress.'],
        });
      }
      await withIdempotentActorCommand(pool, actor(), idempotencyKey ?? '', requestHash, async (c) => {
        await records.issueContingencyPack(c, {
          batchId: f.batchId, batchLabel: f.batchNumber, moment: body.moment, stageRef: body.stageRef ?? null, templateRef: body.templateRef,
          destination: body.destination, pages: body.pages, reason: body.reason,
        });
        return null;
      });
      return formsView(app, pool, f.batchId);
    },
    formEvent: async ({ params, body, actor, idempotencyKey, requestHash }) => {
      const batchId = (await pool.query<{ b: string }>('select batch_id as b from records.contingency_form where id = $1', [params.formId])).rows[0]?.b;
      if (!batchId) {
        throw refusal(404, { code: 'EBMR-API-NO-FORM', kind: 'INVALID_INPUT', whatHappened: 'This contingency form was not found.', why: `${params.formId} is no issued form.`, whatYouCanDo: ['Reload the batch.'] });
      }
      await withIdempotentActorCommand(pool, actor(), idempotencyKey ?? '', requestHash, async (c) => {
        await records.recordContingencyFormEvent(c, params.formId, body.event, body.reason ?? null, body.reference ?? null);
        return null;
      });
      return formsView(app, pool, batchId);
    },
    pdf: async ({ params, actor }) => {
      const f = await facts(pool, params.batchId);
      const bundle = await inSnapshot(pool, actor(), (c) => batchBundle(c, f));
      const out = await records.renderTrueCopyPdf(bundle, { title: pdfTitle(f), label: `Batch ${f.batchNumber}` });
      return { fileName: `${f.batchNumber}-true-copy.pdf`, pdfBase64: Buffer.from(out.pdf).toString('base64'), pdfSha256: out.pdfSha256, contentSha256: out.contentSha256, recordDate: out.recordDate };
    },
    assembleExport: async ({ params, actor, idempotencyKey, requestHash }) => {
      const f = await facts(pool, params.batchId);
      // The bundles and the PDF from one snapshot; the registration that follows is checked again by the database.
      const built = await inSnapshot(pool, actor(), (c) => buildExport(c, app, f));
      const out = await withIdempotentActorCommand(pool, actor(), idempotencyKey ?? '', requestHash, async (c) => {
        for (const b of built.bundles) await records.registerTrueCopy(c, b.bundle, `Evidence export of batch ${f.batchNumber}`);
        return records.registerEvidenceExport(c, built.exp);
      });
      return one(exportsWhere(app, pool, 'e.id = $1::uuid', [out.result]), 'the export');
    },
    inspection: async ({ actor }) => {
      await withActorCommand(pool, actor(), (c) => c.query("select iam.require_permission('ARCHIVE.INSPECT', '{}'::jsonb)")).catch((e: unknown) => {
        throw commands.asKernelError(e);
      });
      return { exports: await exportsWhere(app, pool, 'exists (select 1 from records.evidence_export_certification c2 where c2.export_id = e.id)', []) };
    },
    exportFile: async ({ params, actor }) => {
      const r = await withActorCommand(pool, actor(), (c) => records.readEvidenceExport(c, params.exportId)).catch((e: unknown) => {
        throw commands.asKernelError(e);
      });
      const label = (await pool.query<{ l: string }>('select subject_label as l from records.evidence_export where id = $1', [params.exportId])).rows[0]?.l ?? 'export';
      return { exportId: r.exportId, fileName: `${label.replace(/[^A-Za-z0-9-]+/g, '-')}-evidence-export.json`, exportSha256: r.exportSha256, text: r.text };
    },
    verify: async ({ body, requireSession }) => {
      requireSession();
      const parsed = (() => {
        try {
          return JSON.parse(body.text) as { exportSha256?: unknown };
        } catch {
          return null;
        }
      })();
      const claimed = typeof parsed?.exportSha256 === 'string' ? parsed.exportSha256 : null;
      const reg = claimed
        ? (await pool.query<{ id: string; label: string; certified: boolean }>(
            `select e.id, e.subject_label as label, exists (select 1 from records.evidence_export_certification c where c.export_id = e.id) as certified
               from records.evidence_export e where e.export_sha256 = $1`,
            [claimed],
          )).rows[0]
        : undefined;
      const report = await records.verifyEvidenceExportText(body.text, reg ? { exportSha256: claimed ?? '' } : undefined);
      const problems = reg ? report.problems : [...report.problems, 'no registered export has this SHA-256: the file is not one this system issued'];
      return {
        ok: problems.length === 0,
        exportSha256: report.exportSha256,
        reference: report.reference,
        registered: reg ? { exportId: reg.id, label: reg.label, certified: reg.certified } : null,
        sections: report.sections,
        problems,
      };
    },
  });
  return Promise.resolve();
}

apps/tablets-server/src/features/records.source:
/**
 * Feature `records` (Phase 4 slice 5b, GMP): record locking and amendment, the bulk reconciliation of a processing
 * record and the bright-stock maximum hold (contract ns/records-lock.ts; recipe-core 0870 to 0873, tablets 1190, 1199;
 * INV-21, R-04, PR-38). Every rule is the database's: the reads come from its tables and definers, the closure, the
 * amendment entries and the maximum hold are the person's own commands, and opening or closing an amendment is the
 * signable action RECORD_LOCK_ACT (signables.ts).
 */
import { routes } from '@ebmr/api-contract';
import type { FastifyInstance } from 'fastify';
import type { AppContext } from '../../platform/context.ts';
import { withIdempotentActorCommand } from '../../platform/db/commands.ts';
import { bindRoutes } from '../../platform/http/bind.ts';
import { refusal } from '../../platform/http/refusal.ts';
import type { SignableActionRegistry } from '../../platform/ports.ts';
import { amendmentView, bulkView, holdList, holdOf, lockList, lockView } from './reads.ts';
import { recordLockActHandler } from './signables.ts';

export function registerSignableActions(registry: SignableActionRegistry, app: AppContext): void {
  if (app.installation !== 'GMP') return;
  registry.register(recordLockActHandler(app));
}

export function plugin(scope: FastifyInstance, app: AppContext): Promise<void> {
  const pool = app.pools.app;
  bindRoutes(scope, app, routes.records, {
    locks: async ({ query, requireSession }) => {
      requireSession();
      return { records: await lockList(app, pool, query.state) };
    },
    lock: async ({ params, requireSession }) => {
      requireSession();
      return lockView(app, pool, params.batchId);
    },
    bulk: async ({ params, requireSession }) => {
      requireSession();
      return bulkView(app, pool, params.batchId);
    },
    closeBulk: async ({ params, body, actor, idempotencyKey, requestHash }) => {
      await withIdempotentActorCommand(pool, actor(), idempotencyKey ?? '', requestHash, async (c) => {
        await c.query('select recipe.close_bulk_reconciliation($1, $2)', [params.batchId, body.remainingHeldReason ?? null]);
        return null;
      });
      return bulkView(app, pool, params.batchId);
    },
    appendAmendmentEntry: async ({ params, body, actor, idempotencyKey, requestHash }) => {
      const n = Number.parseInt(params.number, 10);
      await withIdempotentActorCommand(pool, actor(), idempotencyKey ?? '', requestHash, async (c) => {
        await c.query('select recipe.append_amendment_entry($1, $2, $3, $4, $5, $6, $7)', [params.batchId, n, body.kind, body.target, body.text, body.value ?? null, body.reason]);
        return null;
      });
      return amendmentView(app, pool, params.batchId, n);
    },
    brightStockHolds: async ({ requireSession }) => {
      requireSession();
      return { holds: await holdList(app, pool) };
    },
    setBrightStockHold: async ({ body, actor, idempotencyKey, requestHash }) => {
      await withIdempotentActorCommand(pool, actor(), idempotencyKey ?? '', requestHash, async (c) => {
        await c.query('select recipe.set_bright_stock_hold($1, $2, $3, $4)', [body.productCode, body.strength, Number.parseInt(body.maxHoldHours, 10), body.reason]);
        return null;
      });
      const hold = await holdOf(app, pool, body.productCode, body.strength.trim());
      if (!hold) throw refusal(409, { code: 'EBMR-LCK-020', kind: 'STALE', whatHappened: 'The maximum hold was not found after it was set.', why: 'Reload the list.', whatYouCanDo: ['Reload the list.'] });
      return hold;
    },
  });
  return Promise.resolve();
}

/**
 * The reads of record locking (Phase 4 slice 5b; contract ns/records-lock.ts): a record's lock and amendments, the bulk
 * reconciliation of a processing batch, the locked records, the bright-stock maximum holds. Every value is the
 * database's (recipe-core 0870 to 0873).
 */
import type pg from 'pg';
import type {
  AmendmentView,
  BrightStockHoldView,
  BulkContainerView,
  BulkOrderView,
  BulkQuantity,
  BulkReconciliationView,
  LockCause,
  LockedRecordKind,
  MarketImpactTaskView,
  RecordLockState,
  RecordLockSummaryView,
  RecordLockView,
} from '@ebmr/api-contract';
import type { AppContext } from '../../platform/context.ts';
import { refusal } from '../../platform/http/refusal.ts';
import { peopleOf, personRef, usOf } from '../common/people.ts';

type Db = Pick<pg.Pool, 'query'>;

function noBatch(batchId: string): Error {
  return refusal(404, { code: 'EBMR-LCK-030', kind: 'INVALID_INPUT', whatHappened: 'There is no GMP batch record with this id.', why: `Batch ${batchId} is no GMP batch.`, whatYouCanDo: ['Open the batch from its list.'] });
}

interface BatchRow {
  batch_number: string;
  kind: LockedRecordKind;
  state: RecordLockState;
}

async function batchOf(db: Db, batchId: string): Promise<BatchRow> {
  const { rows } = await db.query<BatchRow>(
    "select b.batch_number, recipe.batch_family_kind(b.id) as kind, recipe.record_lock_state(b.id) as state from recipe.batch_execution b where b.id = $1 and b.purpose = 'GMP_BATCH'",
    [batchId],
  );
  const r = rows[0];
  if (!r) throw noBatch(batchId);
  return r;
}

interface AmendmentRow {
  id: string;
  number: number;
  basis_kind: 'DEVIATION' | 'CHANGE_RECORD';
  basis_id: string;
  basis_ref: string;
  reason_text: string;
  person_id: string;
  role_code: string | null;
  opened_us: string;
  signature_id: string;
  suspended: { lot_id: string; lot_code: string }[];
  close: { person_id: string; role_code: string | null; us: string; signature_id: string; statement: string } | null;
  entries: { id: string; seq: number; kind: AmendmentView['entries'][number]['kind']; target: string; body: string; value: string | null; reason: string; person_id: string; role_code: string | null; us: string }[];
  tasks: { id: string; lot_id: string; lot_code: string; market: 'IN' | 'US' | 'EU'; now: string | null; us: string }[];
}

async function amendmentsOf(app: AppContext, db: Db, batchId: string, number?: number): Promise<AmendmentView[]> {
  const { rows } = await db.query<AmendmentRow>(
    `select a.id, a.number, a.basis_kind, coalesce(a.deviation_id, a.change_record_id) as basis_id,
            coalesce((select d.ref from site.deviation d where d.id = a.deviation_id), (select c.number from recipe.change_record c where c.id = a.change_record_id)) as basis_ref,
            a.reason_text, a.person_id, a.role_code, ${usOf('a.opened_at')} as opened_us, a.signature_id,
            coalesce((select jsonb_agg(jsonb_build_object('lot_id', l, 'lot_code', (select m.lot_code from site.material_lot m where m.id = l)) order by l)
                        from unnest(a.suspended_lots) l), '[]'::jsonb) as suspended,
            (select jsonb_build_object('person_id', x.person_id, 'role_code', x.role_code, 'us', ${usOf('x.closed_at')}, 'signature_id', x.signature_id, 'statement', x.statement)
               from recipe.record_amendment_close x where x.amendment_id = a.id) as close,
            coalesce((select jsonb_agg(jsonb_build_object('id', e.id, 'seq', e.seq, 'kind', e.kind, 'target', e.target, 'body', e.body, 'value', e.value, 'reason', e.reason,
                                                          'person_id', e.person_id, 'role_code', e.role_code, 'us', ${usOf('e.recorded_at')}) order by e.seq)
                        from recipe.record_amendment_entry e where e.amendment_id = a.id), '[]'::jsonb) as entries,
            coalesce((select jsonb_agg(jsonb_build_object('id', t.id, 'lot_id', t.lot_id, 'lot_code', (select m.lot_code from site.material_lot m where m.id = t.lot_id),
                                                          'market', t.market,
                                                          'now', case t.market when 'IN' then recipe.manufacturer_release_state(t.lot_id) else recipe.disposition_state(t.lot_id, t.market) end,
                                                          'us', ${usOf('t.opened_at')}) order by t.lot_id, t.market)
                        from recipe.amendment_market_task t where t.amendment_id = a.id), '[]'::jsonb) as tasks
       from recipe.record_amendment a
      where a.batch_id = $1 and ($2::int is null or a.number = $2::int)
      order by a.number`,
    [batchId, number ?? null],
  );
  const people = await peopleOf(db, rows.flatMap((r) => [r.person_id, r.close?.person_id, ...r.entries.map((e) => e.person_id)]));
  return rows.map((r): AmendmentView => {
    const open = r.close === null;
    return {
      amendmentId: r.id,
      number: r.number,
      batchId,
      state: open ? 'OPEN' : 'CLOSED',
      basis: { kind: r.basis_kind, id: r.basis_id, ref: r.basis_ref },
      reason: r.reason_text,
      openedBy: personRef(people, r.person_id, r.role_code ?? 'QA'),
      openedAt: app.formatInstant(r.opened_us),
      openSignatureId: r.signature_id,
      closedBy: r.close ? personRef(people, r.close.person_id, r.close.role_code ?? 'QA') : null,
      closedAt: r.close ? app.formatInstant(r.close.us) : null,
      closeSignatureId: r.close?.signature_id ?? null,
      closingStatement: r.close?.statement ?? null,
      entries: r.entries.map((e) => ({
        entryId: e.id,
        seq: e.seq,
        kind: e.kind,
        target: e.target,
        text: e.body,
        value: e.value,
        reason: e.reason,
        by: personRef(people, e.person_id, e.role_code ?? 'OPERATOR'),
        at: app.formatInstant(e.us),
      })),
      suspendedLots: r.suspended.map((l) => ({ lotId: l.lot_id, lotCode: l.lot_code })),
      tasks: r.tasks.map((t): MarketImpactTaskView => ({
        taskId: t.id,
        lotId: t.lot_id,
        lotCode: t.lot_code,
        market: t.market,
        ownerRole: 'AUTHORISED_PERSON',
        state: open || t.now === 'RELEASE_SUSPENDED' ? 'OPEN' : 'DONE',
        dispositionNow: t.now,
        openedAt: app.formatInstant(t.us),
      })),
    };
  });
}

/** One amendment of the record by its number (after an entry is appended). */
export async function amendmentView(app: AppContext, db: Db, batchId: string, number: number): Promise<AmendmentView> {
  await batchOf(db, batchId);
  const [a] = await amendmentsOf(app, db, batchId, number);
  if (!a) throw refusal(404, { code: 'EBMR-LCK-040', kind: 'INVALID_INPUT', whatHappened: 'There is no such amendment of the record.', why: `Amendment ${number} of batch ${batchId} does not exist.`, whatYouCanDo: ['Reload the record.'] });
  return a;
}

export async function lockView(app: AppContext, db: Db, batchId: string): Promise<RecordLockView> {
  const b = await batchOf(db, batchId);
  const { rows } = await db.query<{ cause: LockCause | null; us: string | null; lots: { lot_id: string; lot_code: string }[] }>(
    `select (select e.cause from recipe.record_lock_event e where e.batch_id = $1 and e.event = 'LOCKED') as cause,
            (select ${usOf('e.recorded_at')} from recipe.record_lock_event e where e.batch_id = $1 and e.event = 'LOCKED') as us,
            recipe.record_released_lots($1) as lots`,
    [batchId],
  );
  const r = rows[0]!;
  const amendments = await amendmentsOf(app, db, batchId);
  const open = amendments.find((a) => a.state === 'OPEN');
  return {
    batchId,
    batchNumber: b.batch_number,
    recordKind: b.kind,
    state: b.state,
    lockedAt: r.us ? app.formatInstant(r.us) : null,
    cause: r.cause,
    amendments,
    nextAmendmentNumber: amendments.length + 1,
    openAmendmentNumber: open?.number ?? null,
    releasedLots: r.lots.map((l) => ({ lotId: l.lot_id, lotCode: l.lot_code })),
  };
}

export async function lockList(app: AppContext, db: Db, state: 'LOCKED' | 'UNDER_AMENDMENT' | undefined): Promise<RecordLockSummaryView[]> {
  const { rows } = await db.query<{ batch_id: string; batch_number: string; kind: LockedRecordKind; state: 'LOCKED' | 'UNDER_AMENDMENT'; cause: LockCause; us: string; open: number | null }>(
    `select e.batch_id, b.batch_number, recipe.batch_family_kind(b.id) as kind, recipe.record_lock_state(b.id) as state, e.cause, ${usOf('e.recorded_at')} as us,
            (select max(a.number) from recipe.record_amendment a where a.batch_id = b.id
                and not exists (select 1 from recipe.record_amendment_close x where x.amendment_id = a.id)) as open
       from recipe.record_lock_event e join recipe.batch_execution b on b.id = e.batch_id
      where e.event = 'LOCKED' and ($1::text is null or recipe.record_lock_state(b.id) = $1::text)
      order by e.recorded_at desc, b.batch_number
      limit 500`,
    [state ?? null],
  );
  return rows.map((r) => ({ batchId: r.batch_id, batchNumber: r.batch_number, recordKind: r.kind, state: r.state, lockedAt: app.formatInstant(r.us), cause: r.cause, openAmendmentNumber: r.open }));
}

interface HoldRow {
  product_code: string;
  strength: string;
  max_hold_hours: number;
  reason: string;
  person_id: string;
  role_code: string | null;
  us: string;
}

async function holdViews(app: AppContext, db: Db, where: string, params: unknown[]): Promise<BrightStockHoldView[]> {
  const { rows } = await db.query<HoldRow>(
    `select distinct on (h.product_code, h.strength) h.product_code, h.strength, h.max_hold_hours, h.reason, h.person_id, h.role_code, ${usOf('h.recorded_at')} as us
       from recipe.bright_stock_max_hold h where ${where}
      order by h.product_code, h.strength, h.recorded_at desc, h.id desc`,
    params,
  );
  const people = await peopleOf(db, rows.map((r) => r.person_id));
  return rows.map((r) => ({
    productCode: r.product_code,
    strength: r.strength,
    maxHoldHours: String(r.max_hold_hours),
    reason: r.reason,
    setBy: personRef(people, r.person_id, r.role_code ?? 'MASTER_DATA_STEWARD'),
    setAt: app.formatInstant(r.us),
  }));
}

export const holdList = (app: AppContext, db: Db): Promise<BrightStockHoldView[]> => holdViews(app, db, 'true', []);

export async function holdOf(app: AppContext, db: Db, productCode: string, strength: string): Promise<BrightStockHoldView | null> {
  return (await holdViews(app, db, 'h.product_code = $1 and h.strength = $2', [productCode, strength]))[0] ?? null;
}

interface ContainerRow {
  id: string;
  label: string;
  quantity: string | null;
  unit: BulkContainerView['unit'];
  state: string | null;
  closed_us: string | null;
  disposition: BulkContainerView['disposition'];
  order_id: string | null;
  order_number: string | null;
  hours: string | null;
  past: boolean;
}

export async function bulkView(app: AppContext, db: Db, batchId: string): Promise<BulkReconciliationView> {
  const b = await batchOf(db, batchId);
  const { rows: containers } = await db.query<ContainerRow>(
    `select c.id, c.label_code as label, x.net_quantity::text as quantity, c.quantity_unit as unit, plant.container_state(c.id) as state,
            case when x.closed_at is null then null else ${usOf('x.closed_at')} end as closed_us,
            recipe.bulk_container_disposition(c.id) as disposition, i.order_batch_id as order_id, o.batch_number as order_number,
            case when x.closed_at is null then null else floor(extract(epoch from clock_timestamp() - x.closed_at) / 3600)::bigint::text end as hours,
            recipe.bright_stock_container_problem(c.id, i.order_batch_id) is not null as past
       from plant.output_container c
       left join plant.container_close x on x.container_id = c.id
       left join recipe.packaging_bulk_issue i on i.container_id = c.id
       left join recipe.batch_execution o on o.id = i.order_batch_id
      where c.batch_id = $1
      order by c.label_code`,
    [batchId],
  );
  const { rows: orders } = await db.query<{ id: string; batch_number: string; status: string | null; issued: BulkQuantity[]; n: number; hold: string | null }>(
    `select o as id, s.batch_number, recipe.order_status(o) as status,
            coalesce((select jsonb_agg(jsonb_build_object('quantity', t.q::text, 'unit', t.u) order by t.u)
                        from (select i.unit as u, sum(i.quantity) as q from recipe.packaging_bulk_issue i where i.order_batch_id = o group by i.unit) t), '[]'::jsonb) as issued,
            (select count(*)::int from recipe.packaging_bulk_issue i where i.order_batch_id = o) as n,
            recipe.bright_stock_hold_problem(o) as hold
       from unnest(recipe.packaging_children_of($1)) o join recipe.stub_batch s on s.id = o
      order by s.batch_number`,
    [batchId],
  );
  const { rows: facts } = await db.query<{
    problems: string[];
    produced: BulkQuantity[];
    issued: BulkQuantity[];
    remaining: BulkQuantity[];
    closure: { person_id: string; role_code: string | null; us: string; reason: string | null } | null;
    product: string | null;
    strength: string | null;
  }>(
    `select recipe.bulk_close_problems($1) as problems,
            coalesce(r.produced, recipe.bulk_totals($1, array['ISSUED', 'CHARGED', 'REJECTED', 'LEFT'])) as produced,
            coalesce(r.issued, recipe.bulk_totals($1, array['ISSUED'])) as issued,
            coalesce(r.remaining, recipe.bulk_totals($1, array['LEFT'])) as remaining,
            case when r.id is null then null
                 else jsonb_build_object('person_id', r.person_id, 'role_code', r.role_code, 'us', ${usOf('r.recorded_at')}, 'reason', r.remaining_held_reason) end as closure,
            recipe.batch_product($1) ->> 'code' as product, recipe.batch_product($1) ->> 'strength' as strength
       from (select 1) one left join recipe.bulk_reconciliation r on r.batch_id = $1`,
    [batchId],
  );
  const f = facts[0]!;
  const people = await peopleOf(db, [f.closure?.person_id]);
  const closed = (s: string | null): boolean => s === 'EXECUTION_COMPLETE' || s === 'ABORTED' || s === 'CANCELLED';
  return {
    batchId,
    batchNumber: b.batch_number,
    recordKind: b.kind,
    produced: f.produced,
    issued: f.issued,
    remaining: f.remaining,
    orders: orders.map((o): BulkOrderView => ({ orderBatchId: o.id, batchNumber: o.batch_number, status: o.status ?? 'PLANNED', closed: closed(o.status), issued: o.issued, containers: o.n, holdProblem: o.hold })),
    containers: containers.map((c): BulkContainerView => ({
      containerId: c.id,
      label: c.label,
      quantity: c.quantity,
      unit: c.unit,
      state: c.state ?? 'OPEN',
      closedAt: c.closed_us ? app.formatInstant(c.closed_us) : null,
      disposition: c.disposition,
      orderBatchId: c.order_id,
      orderBatchNumber: c.order_number,
      heldHours: c.hours,
      pastMaxHold: c.past,
    })),
    maxHold: f.product && f.strength ? await holdOf(app, db, f.product, f.strength) : null,
    closeProblems: f.problems,
    closure: f.closure
      ? { closedBy: personRef(people, f.closure.person_id, f.closure.role_code ?? 'HEAD_OF_PRODUCTION'), closedAt: app.formatInstant(f.closure.us), remainingHeldReason: f.closure.reason }
      : null,
    lockState: b.state,
  };
}

/**
 * The signed acts of record locking (Phase 4 slice 5b; signable action RECORD_LOCK_ACT). Each signs the record the
 * database act works on and runs that act with the signature in the same transaction; the database decides
 * (recipe-core 0872) and a refusal signs nothing (esig/db-acts.ts).
 *
 *   AMENDMENT_OPEN   record_lock <batch>/<n>/OPEN/<DEVIATION|CHANGE_RECORD>/<basis>  AMENDMENT_OPENED (QA)  recipe.open_record_amendment
 *                    (exactly one of deviationId, changeRecordId; the person's own reason)
 *   AMENDMENT_CLOSE  record_lock <batch>/<n>/CLOSE                                 AMENDMENT_CLOSED (QA)  recipe.close_record_amendment
 *                    (the closing statement; n is the open amendment's number)
 */
import type { SignableAction } from '@ebmr/api-contract';
import type pg from 'pg';
import type { AppContext } from '../../platform/context.ts';
import type { DryRunOutcome, SignableActionHandler } from '../../platform/ports.ts';
import { dbActHandler, refusedOutcome, type ActTarget } from '../esig/db-acts.ts';

type RecordLockAct = Extract<SignableAction, { kind: 'RECORD_LOCK_ACT' }>;

const meaningOf = (a: RecordLockAct): string => (a.act === 'AMENDMENT_OPEN' ? 'AMENDMENT_OPENED' : 'AMENDMENT_CLOSED');
const basisOf = (a: RecordLockAct): { kind: 'DEVIATION' | 'CHANGE_RECORD'; id: string } | null =>
  a.input.deviationId !== undefined ? { kind: 'DEVIATION', id: a.input.deviationId } : a.input.changeRecordId !== undefined ? { kind: 'CHANGE_RECORD', id: a.input.changeRecordId } : null;

async function targetNow(db: pg.Pool | pg.PoolClient, a: RecordLockAct): Promise<ActTarget> {
  const b = basisOf(a);
  const { rows } = await db.query<{ a: string | null; s: string }>('select recipe.record_lock_next_id($1, $2, $3, $4) as a, recipe.record_lock_state($1) as s', [
    a.batchId, a.act === 'AMENDMENT_OPEN' ? 'OPEN' : 'CLOSE', b?.kind ?? null, b?.id ?? null,
  ]);
  // No open amendment to close: a number no amendment has, so the dry run answers "no record" (404). The state signed is
  // the record's (LOCKED to open, UNDER_AMENDMENT to close); the database checks it again.
  return { aggregateType: 'record_lock', aggregateId: rows[0]?.a ?? `${a.batchId}/0/CLOSE`, meaning: meaningOf(a), expectedState: rows[0]?.s ?? 'UNLOCKED' };
}

function inputRefusal(a: RecordLockAct): DryRunOutcome | null {
  const i = a.input;
  const ok =
    a.act === 'AMENDMENT_OPEN'
      ? (i.deviationId === undefined) !== (i.changeRecordId === undefined) && i.reason !== undefined && i.statement === undefined
      : i.statement !== undefined && i.deviationId === undefined && i.changeRecordId === undefined && i.reason === undefined;
  if (ok) return null;
  return refusedOutcome(422, 'EBMR-API-ACT-INPUT', 'The act does not carry what it needs. Nothing was signed.',
    a.act === 'AMENDMENT_OPEN'
      ? 'An amendment is opened under exactly one basis (deviationId or changeRecordId) with the person\'s own reason.'
      : 'An amendment is closed with a closing statement and nothing else.',
    ['DI-37', 'INV-21'], ['Reload the screen and sign again.']);
}

export function recordLockActHandler(app: AppContext): SignableActionHandler<RecordLockAct> {
  return dbActHandler<RecordLockAct>(app, {
    kind: 'RECORD_LOCK_ACT',
    aggregateTypes: ['record_lock'],
    target: (a) => {
      const b = basisOf(a);
      return { aggregateType: 'record_lock', aggregateId: a.act === 'AMENDMENT_OPEN' && b ? `${a.batchId}/?/OPEN/${b.kind}/${b.id}` : `${a.batchId}/?/CLOSE`, meaning: meaningOf(a) };
    },
    targetNow,
    reasonOf: (a) => (a.act === 'AMENDMENT_OPEN' && a.input.reason ? { reasonCode: a.input.reason.code, reasonText: a.input.reason.text } : undefined),
    precheck: (_client, _ctx, a) => Promise.resolve(inputRefusal(a)),
    async apply(client, _ctx, a, signatureId) {
      if (a.act === 'AMENDMENT_OPEN') {
        const b = basisOf(a)!;
        const { rows } = await client.query<{ id: string }>('select recipe.open_record_amendment($1, $2, $3, $4, $5, $6) as id', [
          a.batchId, b.kind, b.id, a.input.reason!.code, a.input.reason!.text, signatureId,
        ]);
        return { act: a.act, batchId: a.batchId, amendmentId: rows[0]!.id };
      }
      const t = await targetNow(client, a);
      const n = Number.parseInt(t.aggregateId.split('/')[1] ?? '0', 10);
      const { rows } = await client.query<{ id: string }>('select recipe.close_record_amendment($1, $2, $3, $4) as id', [a.batchId, n, a.input.statement, signatureId]);
      return { act: a.act, batchId: a.batchId, amendmentId: rows[0]!.id };
    },
  });
}

apps/tablets-server/test/records/records.source:
/**
 * The records routes and acts over HTTP (Phase 4 slice 5b; contract ns/records-lock.ts; recipe-core 0870 to 0873,
 * tablets 1190, 1199): the bulk reconciliation of a processing batch closed by production (the record locks), the lock
 * and its amendment opened and closed by QA through the ceremony (RECORD_LOCK_ACT, the aggregate id read by the server),
 * entries appended by production, the bright-stock maximum hold set by master data, and every refusal from the database.
 * The batch is a real GMP batch, issued; its execution end is arranged (the engine paths are proven elsewhere).
 */
import { randomUUID } from 'node:crypto';
import { afterAll, beforeAll, describe, expect, it } from 'vitest';
import { routes, type SignableAction } from '@ebmr/api-contract';
import { withCommand } from '@ebmr/kernel';
import { refusalOf, valueOf } from '../esig/support.ts';
import { actorOf, startGmpBatchWorld, type GmpBatchWorld } from '../support/gmp-world.ts';
import type { TestBrowser } from '../support/harness.ts';
import { describeAction, signAction } from '../support/signed-acts.ts';

let w: GmpBatchWorld;
let head: TestBrowser;
let qa: TestBrowser;
let qa2: TestBrowser;
let steward: TestBrowser;
let batchId: string;
let deviationId: string;
let containerId: string;

beforeAll(async () => {
  w = await startGmpBatchWorld();
  const issuer = await w.gmp.asPersona('issuer');
  [head, qa, qa2, steward] = await Promise.all([w.gmp.asPersona('head1'), w.gmp.asPersona('qaInvestigator'), w.gmp.asPersona('qaApprover2'), w.gmp.asPersona('steward')]);
  batchId = await w.issued(issuer);
  // ARRANGED: the batch's execution is complete (the engine's own end is proven by the execution tests).
  await w.gmp.db.admin.query("update recipe.execution_state set status = 'EXECUTION_COMPLETE' where batch_id = $1", [batchId]);
  // ARRANGED: one closed output container released by QA and never issued (the container paths are proven elsewhere).
  const fx = await w.gmp.db.admin.connect();
  try {
    await fx.query('begin');
    await fx.query("set local session_replication_role = 'replica'");
    const [b] = (await fx.query<{ n: string; p: string; s: string }>("select batch_number as n, recipe.batch_product(id) ->> 'code' as p, recipe.batch_product(id) ->> 'strength' as s from recipe.batch_execution where id = $1", [batchId])).rows;
    containerId = randomUUID();
    await fx.query(`insert into plant.output_container (id, label_code, batch_id, batch_number, product_code, strength, stage, quantity_unit, opened_by_person, opened_by_account)
                    values ($1, $2, $3, $4, $5, $6, 'COMPRESSION', 'kg', $1, $1)`, [containerId, `OC-${b!.n}-4711`, batchId, b!.n, b!.p, b!.s]);
    await fx.query("insert into plant.container_close (container_id, net_quantity, person_id, account_id, basis, weighing) values ($1, 12.500, $1, $1, 'WEIGHED', '{}'::jsonb)", [containerId]);
    await fx.query("insert into platform.aggregate_state (aggregate_type, aggregate_id, machine_code, machine_version, state, version) values ('output_container', $1, 'output_container', 1, 'RELEASED_BY_QA', 3)", [containerId]);
    await fx.query('commit');
  } finally {
    fx.release();
  }
  const operator = await actorOf(w.gmp, 'qaInvestigator');
  deviationId = await withCommand(w.gmp.db.app, { ...operator, correlationId: randomUUID() }, async (c) => {
    const d = (await c.query<{ r: { deviationId: string } }>('select site.raise_deviation($1::jsonb) as r', [
      JSON.stringify({ kind: 'DEVIATION', title: 'Record finding after closure', classification: 'MINOR', riskRationale: 'Documentation finding; assessed by QA' }),
    ])).rows[0]!.r.deviationId;
    await c.query("select site.link_deviation($1, 'BATCH', $2)", [d, batchId]);
    return d;
  });
}, 600_000);
afterAll(async () => {
  await w?.close();
});

const codeOf = (r: Awaited<ReturnType<typeof signAction>>): string => (r.ok ? 'ok' : (refusalOf(r)?.why.match(/EBMR-[A-Z]+-\d{3}/)?.[0] ?? refusalOf(r)?.code ?? 'refused'));

describe('records routes over HTTP (outline 5.2.10; INV-21, PR-38)', () => {

  it('[INV-21] production closes the bulk reconciliation of a complete processing batch and the record locks; QA cannot close it; the lock and the list show it; an unknown batch is 404', async () => {
    const before = valueOf(await head.call(routes.records.bulk, { params: { batchId } }));
    expect(before).toMatchObject({ batchId, recordKind: 'PROCESSING', closeProblems: [], closure: null, lockState: 'UNLOCKED', orders: [],
                                   produced: [{ quantity: '12.500', unit: 'kg' }], issued: [], remaining: [{ quantity: '12.500', unit: 'kg' }] });
    expect(before.containers).toEqual([expect.objectContaining({ containerId, quantity: '12.500', unit: 'kg', state: 'RELEASED_BY_QA', orderBatchId: null, orderBatchNumber: null })]);
    expect(before.containers[0]!.closedAt).toBeTruthy();
    expect(refusalOf(await qa.call(routes.records.closeBulk, { params: { batchId }, body: {} })).code).toBe('EBMR-IAM-040');
    // Bulk is left: production closes only with the reason it is held (EBMR-LCK-012), and the reason is recorded.
    expect(refusalOf(await head.call(routes.records.closeBulk, { params: { batchId }, body: {} }))).toMatchObject({ code: 'EBMR-LCK-012', why: expect.stringMatching(/1 container\(s\) of bulk are left/) as string });
    const after = valueOf(await head.call(routes.records.closeBulk, { params: { batchId }, body: { remainingHeldReason: 'Left over bulk held for a later order under review' } }));
    expect(after).toMatchObject({ lockState: 'LOCKED', closeProblems: ['the bulk reconciliation is already closed'],
                                  closure: { closedBy: { legalName: 'Lakshmi Iyengar', role: 'HEAD_OF_PRODUCTION' }, remainingHeldReason: 'Left over bulk held for a later order under review' } });
    expect(after.closure!.closedAt).toBeTruthy();
    const again = refusalOf(await head.call(routes.records.closeBulk, { params: { batchId }, body: { remainingHeldReason: 'Left over bulk held for a later order under review' } }));
    expect(again).toMatchObject({ code: 'EBMR-LCK-011', why: expect.stringMatching(/already closed/) as string });
    const lock = valueOf(await qa.call(routes.records.lock, { params: { batchId } }));
    expect(lock).toMatchObject({ state: 'LOCKED', cause: 'BULK_RECONCILIATION_CLOSED', amendments: [], nextAmendmentNumber: 1, openAmendmentNumber: null, releasedLots: [] });
    expect(valueOf(await qa.call(routes.records.locks, { query: { state: 'LOCKED' } })).records.map((r) => r.batchId)).toContain(batchId);
    expect(valueOf(await qa.call(routes.records.locks, { query: { state: 'UNDER_AMENDMENT' } })).records.map((r) => r.batchId)).not.toContain(batchId);
    const unknown = randomUUID();
    expect(refusalOf(await qa.call(routes.records.lock, { params: { batchId: unknown } }))).toMatchObject({
      status: 404, code: 'EBMR-LCK-030', why: expect.stringContaining(unknown) as string, whatYouCanDo: [expect.stringMatching(/./) as string],
    });
    // Every read needs a session.
    const anon = w.gmp.browser();
    expect(refusalOf(await anon.call(routes.records.locks, { query: {} })).status).toBe(401);
    expect(refusalOf(await anon.call(routes.records.lock, { params: { batchId } })).status).toBe(401);
    expect(refusalOf(await anon.call(routes.records.bulk, { params: { batchId } })).status).toBe(401);
    expect(refusalOf(await anon.call(routes.records.brightStockHolds)).status).toBe(401);
  });

  it('[INV-21][R-04] QA opens an amendment through the ceremony (the server reads its number), production appends an entry, another QA person closes it over the entries: LOCKED again; a malformed act signs nothing', async () => {
    const open: SignableAction = { kind: 'RECORD_LOCK_ACT', act: 'AMENDMENT_OPEN', batchId, input: { deviationId, reason: { code: 'LATE_ENTRY', text: 'Untranscribed check found at review' } } };
    expect(await describeAction(qa, open)).toMatchObject({ aggregateType: 'record_lock', aggregateId: `${batchId}/1/OPEN/DEVIATION/${deviationId}`, meaning: 'AMENDMENT_OPENED', expectedState: 'LOCKED' });
    expect(codeOf(await signAction(w.gmp, qa, 'qaInvestigator', { ...open, input: { deviationId } }))).toBe('EBMR-API-ACT-INPUT');
    expect(codeOf(await signAction(w.gmp, qa, 'qaInvestigator', { ...open, input: { ...open.input, statement: 'not for an opening' } }))).toBe('EBMR-API-ACT-INPUT');
    expect(codeOf(await signAction(w.gmp, head, 'head1', open))).not.toBe('ok');
    expect(codeOf(await signAction(w.gmp, qa, 'qaInvestigator', open))).toBe('ok');
    const opened = valueOf(await qa.call(routes.records.lock, { params: { batchId } }));
    expect(opened).toMatchObject({ state: 'UNDER_AMENDMENT', openAmendmentNumber: 1, nextAmendmentNumber: 2 });
    expect(opened.amendments[0]).toMatchObject({ number: 1, state: 'OPEN', basis: { kind: 'DEVIATION', id: deviationId }, openedBy: { legalName: 'Divya Menon', role: 'QA_REVIEWER' }, entries: [], tasks: [] });

    const entry = { kind: 'LATE_ENTRY' as const, target: 'Step s-blend: blend time', text: 'Blend time read from the paper log', value: '12 min', reason: 'Transcribed from paper log PL-7 under the deviation' };
    expect(refusalOf(await qa.call(routes.records.appendAmendmentEntry, { params: { batchId, number: '1' }, body: entry })).code).toBe('EBMR-IAM-040');
    expect(refusalOf(await head.call(routes.records.appendAmendmentEntry, { params: { batchId, number: '2' }, body: entry })).code).toBe('EBMR-LCK-040');
    const amended = valueOf(await head.call(routes.records.appendAmendmentEntry, { params: { batchId, number: '1' }, body: entry }));
    expect(amended.entries).toEqual([expect.objectContaining({ seq: 1, kind: 'LATE_ENTRY', value: '12 min', by: expect.objectContaining({ legalName: 'Lakshmi Iyengar', role: 'HEAD_OF_PRODUCTION' }) as unknown })]);

    const close: SignableAction = { kind: 'RECORD_LOCK_ACT', act: 'AMENDMENT_CLOSE', batchId, input: { statement: 'The late entry restores the record; no product impact' } };
    expect(await describeAction(qa2, close)).toMatchObject({ aggregateId: `${batchId}/1/CLOSE`, meaning: 'AMENDMENT_CLOSED', expectedState: 'UNDER_AMENDMENT' });
    expect(codeOf(await signAction(w.gmp, qa2, 'qaApprover2', { ...close, input: {} }))).toBe('EBMR-API-ACT-INPUT');
    expect(codeOf(await signAction(w.gmp, qa2, 'qaApprover2', close))).toBe('ok');
    const closed = valueOf(await qa.call(routes.records.lock, { params: { batchId } }));
    expect(closed).toMatchObject({ state: 'LOCKED', openAmendmentNumber: null });
    expect(closed.amendments[0]).toMatchObject({ state: 'CLOSED', closedBy: { legalName: 'Arvind Rao' }, closingStatement: 'The late entry restores the record; no product impact' });
    // Nothing open to close: the record to be signed does not exist.
    expect(codeOf(await signAction(w.gmp, qa2, 'qaApprover2', close))).not.toBe('ok');
    // A second amendment: an entry goes to the amendment named, never to the first.
    const open2: SignableAction = { ...open, input: { deviationId, reason: { code: 'CORRECTION', text: 'Second finding under the same deviation' } } };
    expect(await describeAction(qa, open2)).toMatchObject({ aggregateId: `${batchId}/2/OPEN/DEVIATION/${deviationId}` });
    expect(codeOf(await signAction(w.gmp, qa, 'qaInvestigator', open2))).toBe('ok');
    const second = valueOf(await head.call(routes.records.appendAmendmentEntry, { params: { batchId, number: '2' }, body: { ...entry, text: 'Second correction', reason: 'Corrected from the paper log PL-8 under the deviation' } }));
    expect(second).toMatchObject({ number: 2, state: 'OPEN', entries: [expect.objectContaining({ seq: 1, text: 'Second correction' }) as unknown] });
  });

  it('[PR-38] master data sets a product\'s maximum hold for bright stock (a new version each time, the latest shown); production cannot; a number travels as text', async () => {
    const product = `HOLD-${randomUUID().slice(0, 6).toUpperCase()}`;
    const body = { productCode: product, strength: '500 mg', maxHoldHours: '720', reason: 'Hold study HS-01: sealed drums, 30 days' };
    expect(refusalOf(await head.call(routes.records.setBrightStockHold, { body })).code).toBe('EBMR-IAM-040');
    expect(valueOf(await steward.call(routes.records.setBrightStockHold, { body }))).toMatchObject({ productCode: product, strength: '500 mg', maxHoldHours: '720', setBy: { legalName: 'Neha Joshi' } });
    expect(valueOf(await steward.call(routes.records.setBrightStockHold, { body: { ...body, maxHoldHours: '480' } }))).toMatchObject({ maxHoldHours: '480' });
    const holds = valueOf(await qa.call(routes.records.brightStockHolds)).holds.filter((h) => h.productCode === product);
    expect(holds).toEqual([expect.objectContaining({ maxHoldHours: '480' })]);
    // The strength is kept as the database keeps it (trimmed), and the hold is found again under it.
    expect(valueOf(await steward.call(routes.records.setBrightStockHold, { body: { ...body, strength: '  250 mg ', maxHoldHours: '96' } }))).toMatchObject({ productCode: product, strength: '250 mg', maxHoldHours: '96' });
    // The batch's own product: its bulk view shows the maximum hold in force.
    const bp = (await w.gmp.db.admin.query<{ p: string; s: string }>("select recipe.batch_product($1) ->> 'code' as p, recipe.batch_product($1) ->> 'strength' as s", [batchId])).rows[0]!;
    valueOf(await steward.call(routes.records.setBrightStockHold, { body: { productCode: bp.p, strength: bp.s, maxHoldHours: '720', reason: 'Hold study HS-02 for the batch product' } }));
    expect(valueOf(await head.call(routes.records.bulk, { params: { batchId } })).maxHold).toMatchObject({ productCode: bp.p, strength: bp.s, maxHoldHours: '720' });
  });
});

